contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address a) public {
        require(c.totalRemaining() != c.totalDistributed());
        c.XBornID(); if (__ESBMC_reverted()) return;
        assert(c.balanceOf(a) < c.totalRemaining() || c.balanceOf(a) == c.totalDistributed());
    }
    receive() external payable {}
}

